const raw = $('Recibir Datos').first().json;
const d = raw.telefono != null ? raw : JSON.parse(raw.query || '{}');
const valido = v => v != null && String(v).trim() !== '' && String(v) !== 'undefined' && String(v) !== 'null';
if (!valido(d.telefono) || !valido(d.fecha)) {
  throw new Error('Datos incompletos para cancelar. Necesito: telefono=' + d.telefono + ', fecha=' + d.fecha + '. Confirmá la fecha del turno a cancelar.');
}
const normTel = t => { let s = String(t).replace(/\D/g, ''); if (s.startsWith('54')) s = s.slice(2); if (s.startsWith('9') && s.length >= 10) s = s.slice(1); return s; };
const telefono = normTel(d.telefono);
const fechaHoy = new Date().toISOString().split('T')[0];
if (d.fecha < fechaHoy) {
  throw new Error('El turno del ' + d.fecha + ' ya pasó y no puede cancelarse. Si querés cancelar un turno futuro, decime la fecha.');
}
const turno_id = telefono + '_' + d.fecha;
return [{ json: { nombre: d.nombre || '', fecha: d.fecha || '', telefono, turno_id, fechaHoy } }];

const normTelFn = t => { let s = String(t).replace(/\D/g, ''); if (s.startsWith('54')) s = s.slice(2); if (s.startsWith('9') && s.length >= 10) s = s.slice(1); return s; };
const preparado = $('Preparar Datos').first().json;
const telBuscado = preparado.telefono;
const fechaBuscada = preparado.fecha;
const busyStates = ['PENDIENTE','CONFIRMADO','RECORDATORIO_ENVIADO'];
const filas = $input.all();
const turnosActivos = filas.filter(i => {
  if (!i.json.turno_id) return false;
  const p = i.json.turno_id.split('_');
  return normTelFn(p[0]) === normTelFn(telBuscado) && p[1] === fechaBuscada && busyStates.includes(i.json.estado_turno);
});
if (turnosActivos.length === 0) {
  return [{ json: { ...preparado, turnoExiste: false, turno_id: preparado.turno_id } }];
}
if (turnosActivos.length > 1) {
  const horas = turnosActivos.map(t => t.json.hora).join(' y ');
  throw new Error('Hay ' + turnosActivos.length + ' turnos activos el ' + fechaBuscada + ': a las ' + horas + '. Preguntale al paciente cuál quiere cancelar e intentá de nuevo.');
}
return [{ json: { ...preparado, turnoExiste: true, turno_id: turnosActivos[0].json.turno_id } }];

const d = $('Verificar Turno').first().json;
const resultado = d.turnoExiste
  ? 'El turno de ' + d.nombre + ' para el ' + d.fecha + ' fue cancelado correctamente. ¿Querés que te busque otro día?'
  : 'No encontré un turno registrado para ' + d.nombre + ' el ' + d.fecha + '. ¿Podés verificar la fecha?';
return [{ json: { resultado } }];
